const body = $input.first().json.body || $input.first().json || {};
const sessionId = String(body.session_id || 'default-session').trim();
const userInput = String(body.input || '').trim();
const source = String(body.source || 'ANTT') === 'PhanDong' ? 'PhanDong' : 'ANTT';

const PG_API = ($env.POSTGRES_API_URL || 'http://postgres_api:5434').replace(/\/+$/, '');
const OPENAI_API_KEY = $env.OPENAI_API_KEY || '';
const OPENAI_BASE_URL = ($env.OPENAI_BASE_URL || 'https://api.openai.com/v1').replace(/\/+$/, '');
const OPENAI_MODEL = $env.OPENAI_MODEL || 'gpt-4o-mini';

if (!userInput) {
  const emptyLine = JSON.stringify({ type: 'item', content: 'Vui lòng nhập nội dung câu hỏi phân tích.' }) + '\n';
  return [{ json: { ndjson: emptyLine } }];
}

const store = $getWorkflowStaticData('global');
if (!store.sessions) store.sessions = {};
if (!store.counter) store.counter = 1;
if (!Array.isArray(store.sessions[sessionId])) store.sessions[sessionId] = [];

let recentArticles = [];
let latestReport = null;

try {
  const [newsRes, repRes] = await Promise.all([
    this.helpers.httpRequest({
      method: 'GET',
      url: `${PG_API}/api/news/paginated?page=1&limit=25&channel=${encodeURIComponent(source)}`,
      json: true,
    }).catch(() => ({ data: [] })),
    this.helpers.httpRequest({
      method: 'GET',
      url: `${PG_API}/api/trend-reports?channel=${encodeURIComponent(source)}&limit=1`,
      json: true,
    }).catch(() => ({ data: [] })),
  ]);
  if (Array.isArray(newsRes?.data)) recentArticles = newsRes.data;
  if (Array.isArray(repRes?.data) && repRes.data[0]) latestReport = repRes.data[0];
} catch {}

const dbContext = recentArticles
  .map((a, i) => `${i + 1}. [${a.publish_date || ''}] [${a.sentiment?.name || 'Trung lập'}] Nguồn: ${a.source?.name || 'N/A'} | Tóm tắt: ${a.summary || ''} | Từ khóa: ${a.keywords || ''} | Link: ${a.link || ''}`)
  .join('\n');

const reportContext = latestReport
  ? `Báo cáo xu hướng gần nhất (${latestReport.period}: ${latestReport.period_start} -> ${latestReport.period_end}):\n${String(latestReport.content || '').slice(0, 1500)}`
  : '';

const historyMsgs = store.sessions[sessionId].slice(-8).map((m) => ({
  role: (m.message?.role || m.role) === 'assistant' ? 'assistant' : 'user',
  content: String(m.message?.content ?? m.content ?? ''),
})).filter((m) => m.content.length > 0);

let answer = '';
if (OPENAI_API_KEY) {
  try {
    const aiRes = await this.helpers.httpRequest({
      method: 'POST',
      url: `${OPENAI_BASE_URL}/chat/completions`,
      headers: {
        Authorization: `Bearer ${OPENAI_API_KEY}`,
        'Content-Type': 'application/json',
      },
      body: {
        model: OPENAI_MODEL,
        messages: [
          {
            role: 'system',
            content: `Bạn là Trợ lý Phân tích Không gian mạng CAHY CyberWatch (kênh dữ liệu hiện tại: ${source}). Hãy trả lời chính xác, chuyên nghiệp bằng tiếng Việt dựa trên dữ liệu thực tế từ cơ sở dữ liệu PostgreSQL dưới đây. Khi trích dẫn bài viết, hãy nêu rõ nguồn, đánh giá sắc thái và đường dẫn gốc.\n\n--- DỮ LIỆU TIN BÀI MỚI NHẤT ---\n${dbContext || 'Chưa có bài viết.'}\n\n--- BÁO CÁO XU HƯỚNG ---\n${reportContext}`,
          },
          ...historyMsgs,
          { role: 'user', content: userInput },
        ],
      },
      json: true,
    });
    answer = aiRes?.choices?.[0]?.message?.content || '';
  } catch (err) {
    answer = `Không thể kết nối OpenAI API lúc này (${err.message || 'error'}). Dữ liệu kênh ${source} hiện ghi nhận ${recentArticles.length} bài viết gần nhất.`;
  }
} else {
  answer = `Chưa cấu hình OPENAI_API_KEY trên n8n localhost. Thống kê nhanh kênh ${source}: ${recentArticles.length} bài viết gần nhất.`;
}

const nowIso = new Date().toISOString();
const nextSessionMsgs = [
  ...store.sessions[sessionId],
  { id: store.counter++, session_id: sessionId, created_at: nowIso, message: { role: 'user', type: 'human', content: userInput } },
  { id: store.counter++, session_id: sessionId, created_at: nowIso, message: { role: 'assistant', type: 'ai', content: answer } }
].slice(-40);
const nextSessions = { ...store.sessions, [sessionId]: nextSessionMsgs };
const sessionKeys = Object.keys(nextSessions);
if (sessionKeys.length > 30) {
  delete nextSessions[sessionKeys[0]];
}
store.sessions = nextSessions;

const lines = [
  JSON.stringify({ type: 'item', content: 'Calling supabase_news_intelligence' }),
  JSON.stringify({ type: 'item', content: answer }),
];
return [{ json: { ndjson: lines.join('\n') + '\n' } }];

const body = $input.first().json.body || $input.first().json || {};
const sessionId = String(body.session_id || '').trim();
const store = $getWorkflowStaticData('global');
const messages = (store.sessions && sessionId && store.sessions[sessionId]) ? store.sessions[sessionId] : [];
return [{ json: { messages } }];

const store = $getWorkflowStaticData('global');
const sessions = store.sessions || {};
const data = [];
for (const items of Object.values(sessions)) {
  if (Array.isArray(items)) {
    for (const item of items) data.push(item);
  }
}
return [{ json: { data } }];
